public ListNode removeNthFromEnd(ListNode head, int n) {
     int i;ListNode fast=head;
    for(i=0;i<n;i++)
    {
        fast=fast.next;
    }
    ListNode slow=head;
    if(fast==null)
    return head.next;
    while(fast.next!=null)
    {
        fast=fast.next;
        slow=slow.next;
    }
    slow.next=slow.next.next;
    return head;
